const normalizedBaseName = computed(() => {
  const cleaned = stripKnownExtensions(editableBaseName.value).trim()
  return cleaned || 'drawing'
})

const footerItems = computed(() => addonsStore.getContributions('editor.footer-items')
  .filter((entry) => entry?.contribution?.id && entry?.contribution?.component)
  .sort((left, right) => Number(left.contribution.order || 0) - Number(right.contribution.order || 0)))

const openedNoteAbsolutePath = computed(() => {
  if (!store.activeVault?.path || !store.openedNotePath) return ''
  return window.path.join(store.activeVault.path, store.openedNotePath)
})

const activeNoteFile = computed(
  () => getActiveNoteFile() || (openedNoteAbsolutePath.value ? null : currentFile.value)
)

const markdown = computed(() => {
  if (typeof activeNoteFile.value?.markdown === 'string') return activeNoteFile.value.markdown
  if (typeof currentFile.value?.markdown === 'string') {
    pushEditorLog('warn', '[elephantnote:editor] active-note-fallback-current-file', {
      openedNotePath: store.openedNotePath || null,
      currentFileId: currentFile.value?.id || null,
      currentFilePath: currentFile.value?.pathname || null,
      markdownLength: currentFile.value.markdown.length
    })
    return currentFile.value.markdown
  }
  return ''
})

const documentMeta = computed(() => {
  const content = markdown.value || ''
  const createdAt = getDocumentCreatedAt(content)
  return {
    title: getDocumentTitle(content, fallbackTitle.value),
    tags: parseMarkdownTags(content),
    date: createdAt ? formatShortDate(createdAt) : formatShortDate(new Date())
  }
})

const editorMarginPx = computed(() => {
  const value = Number(preferencesStore.noteEditorMargin)
  if (!Number.isFinite(value)) return 12
  return Math.max(8, Math.min(48, Math.round(value)))
})

const currentNoteRelativePath = computed(() => {
  if (store.openedNotePath) return store.openedNotePath
  const pathname = currentFile.value?.pathname
  const vaultPath = store.activeVault?.path
  if (!pathname || !vaultPath) return ''
  const relativePath = window.path.relative(vaultPath, pathname)
  if (!relativePath || relativePath.startsWith('..') || window.path.isAbsolute(relativePath))
    return ''
  return relativePath
})

const isPinned = computed(() => {
  const pathname = currentNoteRelativePath.value
  return !!pathname && store.pinnedNotePaths.includes(pathname)
})

const currentNoteDirectory = computed(() => {
  const pathname =
    activeNoteFile.value?.pathname || currentFile.value?.pathname || openedNoteAbsolutePath.value
  if (pathname) return window.path.dirname(pathname)
  if (store.activeVault?.path) {
    return window.path.join(store.activeVault.path, store.currentPath || '')
  }
  return ''
})

const vaultAssetsDirectory = computed(() =>
  store.activeVault?.path ? window.path.join(store.activeVault.path, ELEPHANTNOTE_ASSETS_DIR) : ''
)

watch(
  () => ({
    notePath: currentNoteRelativePath.value || store.openedNotePath,
    markdown: markdown.value,
    file: activeNoteFile.value || currentFile.value
  }),
  ({ notePath, markdown: nextMarkdown, file }, previous) => {
    if (!notePath || !file?.id || typeof nextMarkdown !== 'string') return
    if (previous?.notePath !== notePath) {
      rememberObservedMarkdown(notePath, nextMarkdown, file, 'vue-watch')
      return
    }
    if (previous?.markdown === nextMarkdown) return
    const editDelta = estimateEditDelta(previous?.markdown, nextMarkdown)
    lastSeenNotePath = notePath
    lastSeenMarkdown = nextMarkdown
    scheduleNoteSave(notePath, nextMarkdown, file, AUTOSAVE_DELAY_MS, 'vue-watch', editDelta)
  }
)

watch(
  [currentNoteRelativePath, () => activeNoteFile.value?.id, () => currentFile.value?.id, () => store.openedNotePath],
  ([notePath, activeFileId, currentFileId, openedPath], previous) => {
    pushEditorLog('info', '[elephantnote:editor] identity-change', {
      notePath: notePath || null,
      activeFileId: activeFileId || null,
      currentFileId: currentFileId || null,
      openedPath: openedPath || null,
      previous: previous ? {
        notePath: previous[0] || null,
        activeFileId: previous[1] || null,
        currentFileId: previous[2] || null,
        openedPath: previous[3] || null
      } : null,
      tabCount: editorStore.tabs.length,
      activeVaultId: store.activeVaultId || null
    })
    pushEditorLog('info', '[elephantnote:editor] input-state', {
      notePath: notePath || null,
      activeFileId: activeFileId || null,
      markdownLength: typeof activeNoteFile.value?.markdown === 'string'
        ? activeNoteFile.value.markdown.length
        : null,
      visibleMarkdownLength: visibleMarkdown.value.length,
      hasEditorDocument: Boolean(activeFileId && typeof activeNoteFile.value?.markdown === 'string')
    })
  },
  { immediate: true }
)

watch(
  () => props.isAddingTag,
  (value) => {
    localAddingTag.value = value
    if (value) focusTagInput()
    if (!value) localEditingIndex.value = -1
  }
)

watch(
  () => props.isEditingTag,
  (value) => {
    localEditingTag.value = value
    if (!value) localEditingIndex.value = -1
  }
)

const featureFlags = ref({
  askAi: true,
  agents: true
})

const visibleToolbarItems = computed(() => toolbarItems.filter((item) => {
  if (item.key === 'ask-ai') return featureFlags.value.askAi
  if (item.key === 'agents') return featureFlags.value.agents
  return true
}))

watch(
  () => props.isEditingTag,
  (value) => {
    localEditingTag.value = value
    if (!value) localEditingIndex.value = -1
  }
)

watch(
  () => props.modelValue,
  (value) => {
    if (value !== localValue.value) localValue.value = value
  }
)

watch(
  () => entryArray(store.entries).length,
  (length, previousLength) => {
    if (length < previousLength) resetVisibleWindow()
  }
)

const isDrawing = computed(() => !isFolder.value && (!!drawingPreview.value || /\.excalidraw(?:\.png)?$/i.test(
  String(props.entry?.path || props.entry?.name || props.entry?.filename || '')
)))

const coreRailItems = computed(() => [
  {
    id: 'vault',
    title: vaultTooltip.value,
    icon: activeVaultIconComponent.value || Vault,
    active: false,
    run: openActiveVaultIconPicker
  },
  {
    id: 'sidebar-toggle',
    title: sidebarVisible.value ? 'Hide sidebar' : 'Show sidebar',
    icon: sidebarVisible.value ? PanelLeftClose : PanelLeftOpen,
    active: false,
    run: toggleSidebar
  },
  { id: 'search', title: 'Search', icon: Search, active: false, run: () => emit('search') }
])

const addonViewItems = computed(() => addonsStore.getContributions('views')
  .filter((entry) => entry?.contribution?.id && entry?.contribution?.title)
  .map((entry) => {
    const contribution = entry.contribution
    return {
      id: addonViewRailId(contribution.id),
      title: contribution.title,
      icon: ADDON_ICON_COMPONENTS[contribution.icon] || Star,
      active: props.activeAddonViewId === contribution.id,
      run: () => emit('open-addon-view', contribution.id)
    }
  }))

const configuredRailOrderSignature = computed(() => JSON.stringify(
  Array.isArray(preferences.iconRailOrder) ? preferences.iconRailOrder : []
))

const visibleRailItems = computed(() => {
  const ids = allRailItemIds.value
  const hidden = new Set(normalizeIconRailHidden(preferences.iconRailHidden, ids))
  const byId = new Map(allRailItems.value.map((item) => [item.id, item]))
  return normalizeIconRailOrder(runtimeRailOrder.value, ids)
    .filter((id) => isIconRailSeparatorId(id) || !hidden.has(id))
    .map((id) => isIconRailSeparatorId(id) ? { id, separator: true } : byId.get(id))
    .filter(Boolean)
})

const layoutSignature = computed(() => JSON.stringify({
  order: normalizeIconRailOrder(runtimeRailOrder.value, allRailItemIds.value),
  hidden: normalizeIconRailHidden(preferences.iconRailHidden, allRailItemIds.value),
  visible: visibleRailIds.value
}))

watch(allRailItemIds, (ids) => {
  const previous = runtimeRailOrder.value
  const next = extendIconRailOrder(previous, ids)
  if (JSON.stringify(previous) === JSON.stringify(next)) return
  runtimeRailOrder.value = next
  pushIconRailLog('layout:extended', {
    previous,
    next,
    added: next.filter((id) => !previous.includes(id))
  })
}, { immediate: true })

watch(layoutSignature, (signature) => {
  const snapshot = JSON.parse(signature)
  if (!snapshot.visible.includes('vault')) showVaultMenu.value = false
  pushIconRailLog('layout:resolved', snapshot)
}, { immediate: true })

const topBarItems = computed(() => addonsStore.getContributions('top-bar.items')
  .filter((entry) => entry?.contribution?.id && entry?.contribution?.component)
  .sort((left, right) => Number(left.contribution.order || 0) - Number(right.contribution.order || 0)))

const sidebarAfterTreeZones = computed(() => addonsStore.getContributions('layout.zones')
  .filter((entry) => entry?.contribution?.zone === 'sidebar.after-tree' && entry?.contribution?.component)
  .sort((left, right) => Number(left.contribution.order || 0) - Number(right.contribution.order || 0)))

const isFolderActive = computed(() => {
  const entryPath = props.entry?.path || ''
  return !!entryPath && (props.activePath === entryPath || props.activePath.startsWith(`${entryPath}/`))
})

watch(isFolderActive, async (active) => {
  if (!active) return
  expanded.value = true
  await ensureChildren()
}, { immediate: true })

const syncClass = computed(() => ({
  'is-unpaired': nav.syncChecked && !nav.hasPairedSyncDevice,
  'is-syncing': nav.syncStatus === 'syncing',
  'is-error': nav.syncStatus === 'error',
  'is-synced': nav.syncStatus === 'synced'
}))

watch(activeVaultPath, (nextPath, previousPath) => {
  if (nextPath === previousPath) return
  nav.clearSyncStatus()
  if (nextPath) refreshSyncStatus()
})

const accessLabel = computed(() => ({
  isolated: 'Limited access',
  trusted: 'Full app access'
}[accessLevel.value] || 'Unknown access'))

const accessDescription = computed(() => ({
  isolated: 'Runs in an isolated Worker and can only use the capabilities listed below.',
  trusted: 'Runs inside ElephantNote and can change the interface, editor and application behavior.'
}[accessLevel.value] || ''))

const permissionLabels = computed(() => {
  const manifest = props.addon?.manifest || {}
  const permissions = manifest.permissions
  const labels = []
  if (Array.isArray(permissions)) labels.push(...permissions)
  else if (permissions && typeof permissions === 'object') {
    for (const scope of permissions.notes?.read || []) labels.push(`Read ${scope}`)
    for (const scope of permissions.notes?.write || []) labels.push(`Write ${scope}`)
    for (const host of permissions.network?.hosts || []) labels.push(`HTTPS ${host}`)
    if (permissions.storage) labels.push('Private storage')
    if (permissions.commands) labels.push('Commands')
    if (permissions.native) labels.push('Native system access')
  }
  const views = Array.isArray(manifest.contributes?.views) ? manifest.contributes.views : []
  for (const view of views) labels.push(`Interactive workspace: ${view?.title || 'Addon'}`)
  return [...new Set(labels)]
})

const builtinCatalogById = computed(() => new Map(
  (addonsStore.manager?.listBuiltinCatalog?.() || []).map((entry) => [entry.manifest.id, entry.manifest])
))

const browserEntries = computed(() => {
  const entriesById = new Map()
  for (const snapshot of filteredInstalledAddons.value) {
    entriesById.set(snapshot.manifest.id, {
      id: snapshot.manifest.id,
      manifest: snapshot.manifest,
      snapshot,
      installed: true,
      available: null
    })
  }
  for (const available of availableAddons.value) {
    const existing = entriesById.get(available.id)
    if (existing) {
      existing.available = available
      continue
    }
    entriesById.set(available.id, {
      id: available.id,
      manifest: available,
      snapshot: null,
      installed: false,
      available
    })
  }
  return [...entriesById.values()]
    .filter((entry) => !installedOnly.value || entry.installed)
    .sort((left, right) => Number(right.installed) - Number(left.installed) || left.manifest.name.localeCompare(right.manifest.name))
})

const selectedPermissions = computed(() => {
  const permissions = selectedEntry.value?.manifest?.permissions
  if (Array.isArray(permissions)) return permissions
  if (!permissions || typeof permissions !== 'object') return []
  const labels = []
  for (const [scope, value] of Object.entries(permissions)) {
    if (Array.isArray(value)) labels.push(...value.map((item) => `${scope}: ${item}`))
    else if (value && typeof value === 'object') {
      for (const [action, enabled] of Object.entries(value)) {
        if (Array.isArray(enabled)) labels.push(...enabled.map((item) => `${scope}.${action}: ${item}`))
        else if (enabled) labels.push(`${scope}.${action}`)
      }
    } else if (value) labels.push(scope)
  }
  return labels
})

const aiModules = computed(() => AI_SUBMODULE_IDS.map((id) => {
  const snapshot = installedById.value.get(id) || null
  const available = availableById.value.get(id) || null
  const manifest = snapshot?.manifest || available || builtinCatalogById.value.get(id)
  return manifest ? { id, manifest, snapshot, available, installed: Boolean(snapshot) } : null
}).filter(Boolean))

watch(browserEntries, (entries) => {
  if (!selectedAddonId.value) return
  if (!entries.some((entry) => entry.id === selectedAddonId.value)) selectedAddonId.value = ''
})

watch(activePage, async (page) => {
  if (page !== 'addons') selectedAddonId.value = ''
  await nextTick()
  if (page === 'packs') dispatchPackEvent(PACK_SEARCH_EVENT, { query: packQuery.value })
})

const activePage = computed(() => {
  const requested = props.page || props.initialPage
  return SUPPORTED_PAGES.has(requested) ? requested : 'chat'
})

const addonProviders = computed(() => addonsStore.getContributions('ai.providers')
  .map((entry) => ({ addonId: entry.addonId, ...(entry.contribution || {}) }))
  .filter((provider) => typeof provider.providerId === 'string' && provider.providerId.trim())
  .map((provider) => ({
    ...provider,
    providerId: provider.providerId.trim(),
    title: provider.title || provider.providerId,
    capabilities: Array.isArray(provider.capabilities) ? provider.capabilities : ['chat']
  })))

watch(() => addonProviders.value.map((provider) => `${provider.addonId}:${provider.providerId}:${provider.capabilities.join(',')}`).join('|'), async () => {
  if (!hydrated.value) return
  const changed = sanitizeRoutes()
  if (changed) scheduleAutosave('addon-provider-removed')
  const routeName = activePage.value
  const capability = routeName === 'embedding' ? 'embedding' : routeName
  const provider = addonProviderFor(form.value.routes[routeName]?.source, capability)
  if (provider && !addonModels.value[provider.providerId]) await loadAddonModels(provider)
})

watch(() => props.status.connected, (connected) => {
  if (!connected) {
    usageOpen.value = false
    closeResetPicker()
  }
})

const addonItems = computed(() => addonsStore.getContributions('views')
  .filter((entry) => entry?.contribution?.id && entry?.contribution?.title)
  .map((entry) => ({
    id: addonViewRailId(entry.contribution.id),
    label: entry.contribution.title,
    source: 'addon',
    iconComponent: ADDON_ICON_COMPONENTS[entry.contribution.icon] || Star
  })))

const legacyAddonItems = computed(() => getAddonSidebarItems(addonsStore.contributions).map((item) => ({
  id: `addon-item:${item.addonId}:${item.id}`,
  label: item.title || item.tooltip || item.id,
  source: 'addon',
  iconComponent: ADDON_ICON_COMPONENTS[item.icon] || Star
})))

const availableItems = computed(() => [
  ...CORE_ICON_RAIL_ITEMS.map((item) => ({
    ...item,
    source: 'core',
    iconComponent: CORE_ICON_COMPONENTS[item.id] || Star
  })),
  ...addonItems.value,
  ...legacyAddonItems.value
])

const configuredOrderSignature = computed(() => JSON.stringify(
  Array.isArray(preferences.iconRailOrder) ? preferences.iconRailOrder : []
))

const orderedItems = computed(() => {
  const byId = new Map(availableItems.value.map((item) => [item.id, item]))
  return orderedIds.value.map((id) => isIconRailSeparatorId(id) ? { id, separator: true } : byId.get(id)).filter(Boolean)
})

watch(availableIds, (ids) => {
  const previous = runtimeOrder.value
  const next = extendIconRailOrder(previous, ids)
  if (JSON.stringify(previous) === JSON.stringify(next)) return
  runtimeOrder.value = next
  pushIconRailLog('settings:layout-extended', {
    previous,
    next,
    added: next.filter((id) => !previous.includes(id))
  })
}, { immediate: true })

const languageOptions = computed(() => {
  void localeRevision.value
  return getLanguageOptions()
})

const addonStandaloneSections = computed(() => {
  const unique = new Map()
  for (const entry of addonSettingsContributions.value) {
    const contribution = entry?.contribution || {}
    if (!contribution.standalone || !contribution.section || unique.has(contribution.section)) continue
    unique.set(contribution.section, {
      id: contribution.section,
      label: contribution.navigationLabel || contribution.title || contribution.section,
      icon: ICONS[contribution.navigationIcon] || Package,
      order: Number.isFinite(contribution.order) ? contribution.order : 1000
    })
  }
  return [...unique.values()].sort((a, b) => a.order - b.order || a.label.localeCompare(b.label))
})

const settingsIndex = computed(() => [
  ...CORE_SETTINGS_INDEX,
  ...addonSettingsContributions.value.map((entry) => {
    const contribution = entry.contribution || {}
    const section = contribution.section || 'addons'
    return {
      id: contribution.id || `${entry.addonId}:${section}`,
      section,
      label: contribution.navigationLabel || contribution.title || entry.addonId,
      description: contribution.description || 'Addon setting.'
    }
  })
].map((entry) => ({
  ...entry,
  sectionLabel: sectionById.value[entry.section]?.label || rememberedSectionMeta.value[entry.section]?.label || entry.section,
  icon: sectionById.value[entry.section]?.icon || rememberedSectionMeta.value[entry.section]?.icon || Package
})))

const searchResults = computed(() => {
  const terms = settingsQuery.value.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean)
  if (!terms.length) return []
  return settingsIndex.value.filter((entry) => {
    const haystack = `${entry.label} ${entry.description} ${entry.sectionLabel}`.toLocaleLowerCase()
    return terms.every((term) => haystack.includes(term))
  })
})

watch(sections, (currentSections) => {
  const next = { ...rememberedSectionMeta.value }
  for (const section of currentSections) next[section.id] = section
  rememberedSectionMeta.value = next
}, { immediate: true })

watch(() => props.initialSection, (section) => {
  const nextSection = normalizeSection(section, { preserveUnknown: true })
  if (activeSection.value !== nextSection) {
    activeSection.value = nextSection
    rememberSection(nextSection)
    settingsQuery.value = ''
    log.info('[settings] initial-section:changed', { section: nextSection })
    scrollContentToTop()
  }
})

const settingsStyle = computed(() => {
  const tokens = getThemeTokens(theme.value)
  return { ...tokens, '--en-card': tokens['--en-soft'], '--en-accent': tokens['--en-primary'], '--en-active-bg': tokens['--selectionColor'], '--en-active-border': tokens['--en-primary'], '--en-active-text': tokens['--en-primary'] }
})

watch([activeSection, activeVaultPath], ([section]) => {
  trashExpanded.value = false
  if (section === 'vaults') loadVaultTrash()
}, { immediate: true })

const conflictSettings = ref({
  retentionDays: 3,
  minimumRetentionDays: 1,
  maximumRetentionDays: 365,
  entries: []
})

const activeVaultName = computed(() => {
  const active = props.vaults.find((vault) => vault?.path === props.activeVaultPath)
  return active?.name || status.value?.activeVault?.name || 'No active vault'
})

const transferLabel = computed(() => {
  const files = Number(status.value?.transferredFiles || 0)
  const bytes = Number(status.value?.transferredBytes || 0)
  return files ? `${files} file${files === 1 ? '' : 's'} · ${formatBytes(bytes)}` : 'No transfer recorded'
})

const validRetention = computed(() => {
  const value = Number(retentionDays.value)
  const minimum = Number(conflictSettings.value?.minimumRetentionDays || 1)
  const maximum = Number(conflictSettings.value?.maximumRetentionDays || 365)
  return Number.isInteger(value) && value >= minimum && value <= maximum
})

const shellRightZones = computed(() => {
  const seen = new Set()
  return addonsStore.getContributions('layout.zones')
    .filter((entry) => entry?.contribution?.zone === 'shell.right' && entry?.contribution?.component)
    .filter((entry) => {
      const id = entry?.contribution?.id || `${entry?.addonId || 'addon'}:shell.right`
      if (seen.has(id)) return false
      seen.add(id)
      return true
    })
    .sort((left, right) => Number(left.contribution.order || 0) - Number(right.contribution.order || 0))
})

watch(
  () => [store.activeWorkspaceView, store.openedNotePath, store.activeVaultId],
  ([workspaceView, openedNotePath]) => {
    if (!CORE_WORKSPACE_VIEWS.has(workspaceView)) {
      store.setWorkspaceView('notes', { record: false })
      activeAddonViewId.value = ''
      return
    }
    if (openedNotePath || workspaceView !== 'notes') activeAddonViewId.value = ''
  }
)

const openedNoteAbsolutePath = computed(() => {
  if (!store.activeVault?.path || !store.openedNotePath) return ''
  return window.path.join(store.activeVault.path, store.openedNotePath)
})

watch(
  [hasOpenNote, openedNoteAbsolutePath, () => store.openedNotePath, () => editorStore.currentFile?.pathname, () => editorStore.tabs.length],
  ([nextOpen, absolutePath, relativePath, currentPath, tabCount], previous) => {
    log.info('[main-content] note-visibility', {
      nextOpen,
      previousOpen: previous?.[0] ?? null,
      absolutePath: absolutePath || null,
      relativePath: relativePath || null,
      currentPath: currentPath || null,
      tabCount,
      activeVaultId: store.activeVaultId || null,
      workspaceView: store.activeWorkspaceView
    })
  },
  { immediate: true }
)

const workspacePanels = computed(() => addonsStore.getContributions('layout.zones')
  .filter((entry) => entry?.contribution?.zone === 'workspace.notes' && entry?.contribution?.component)
  .sort((left, right) => Number(left.contribution.order || 0) - Number(right.contribution.order || 0)))

watch(() => props.viewId, () => {
  activeList.value = 'inbox'
  selectedTaskId.value = ''
  void load()
}, { immediate: true })

const sections = ref([
  { id: 'filters', title: 'Filtres', open: true },
  { id: 'groups', title: 'Groupes', open: false },
  { id: 'display', title: 'Afficher', open: false },
  { id: 'forces', title: 'Forces', open: false }
])

const indexReady = computed(() => {
  const g = searchStore.indexInspection?.graph
  return Array.isArray(g?.nodes) && g.nodes.length > 0
})

const fallbackGraph = computed(() => {
  if (indexReady.value) return null
  const entries = store.rootEntries || []
  if (entries.length === 0) return null
  return buildGraphFromVaultEntries(entries)
})

const rawGraph = computed(() => {
  if (indexReady.value) {
    return selectSemanticGraphSource({
      inspectionGraph: searchStore.indexInspection?.graph
    })
  }
  return fallbackGraph.value || { nodes: [], edges: [], clusters: [] }
})

const semanticModel = computed(() => {
  const nodeCount = rawGraph.value?.nodes?.length || 0
  const scale = Math.max(1, Math.sqrt(nodeCount) / 12)
  return buildSemanticViewModel({
    graph: rawGraph.value,
    savedPositions: canvasStore.canvasPositions,
    width: Math.round(1800 * scale),
    height: Math.round(1200 * scale)
  })
})

const filteredNodes = computed(() => {
  const nodes = semanticModel.value.nodes
  const q = filterQuery.value.trim().toLowerCase()
  if (!q) return nodes
  return nodes.filter((n) => {
    const title = String(n.title || '').toLowerCase()
    const tags = Array.isArray(n.tags) ? n.tags.join(' ').toLowerCase() : ''
    return title.includes(q) || tags.includes(q)
  })
})

const filteredEdges = computed(() => {
  const candidate = semanticModel.value.edges.filter((e) =>
    filteredNodeIds.value.has(e.source) && filteredNodeIds.value.has(e.target)
  )
  if (candidate.length <= MAX_VISIBLE_EDGES) return candidate
  const sorted = [...candidate].sort((a, b) => Number(b.weight || 0) - Number(a.weight || 0))
  return sorted.slice(0, MAX_VISIBLE_EDGES)
})

const renderEdges = computed(() => {
  const edges = semanticModel.value.edges
  if (edges.length <= MAX_VISIBLE_EDGES) return edges
  const sorted = [...edges].sort((a, b) => Number(b.weight || 0) - Number(a.weight || 0))
  return sorted.slice(0, MAX_VISIBLE_EDGES)
})

const statusMessage = computed(() => {
  if (indexBuilding.value) return 'Construction de l\'index sémantique…'
  if (searchStore.status.status === 'indexing') return searchStore.status.message || 'Indexation…'
  if (displayData.value.nodes.length === 0) {
    if (store.rootEntries?.length > 0) return 'Aucune note à afficher. Ajustez les filtres.'
    return 'Aucun vault chargé.'
  }
  return ''
})

const cardStyle = computed(() => {
  if (cardPos.x === null) return {}
  return { left: `${cardPos.x}px`, top: `${cardPos.y}px` }
})

const timelapseLabel = computed(() => {
  const nodes = displayData.value.nodes
  if (!nodes.length) return '—'
  const sorted = [...nodes].sort((a, b) => {
    const da = new Date(a.updatedAt || 0).getTime()
    const db = new Date(b.updatedAt || 0).getTime()
    return da - db
  })
  const idx = Math.min(sorted.length - 1, Math.floor((timelapseProgress.value / 100) * sorted.length))
  const node = sorted[idx]
  if (!node?.updatedAt) return `Note ${idx + 1}/${sorted.length}`
  return new Date(node.updatedAt).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' })
})

watch(() => store.rootEntries, () => {
  if (!indexReady.value) {
    loadGraphData()
    scheduleGraphMount()
  }
}, { deep: false })

watch([nodeSizeScale, linkThickness, labelThreshold, showLabels], () => {
  if (renderer) renderer.refresh()
})

watch(theme, () => {
  if (!graphInstance || !renderer) return
  const t = theme.value
  const { edgeCounts, maxEdges } = graphData.value || {}
  graphInstance.forEachNode((node, attrs) => {
    const connectivity = (edgeCounts?.get(node) || 0) / (maxEdges || 1)
    graphInstance.setNodeAttribute(node, 'color', nodeColor(t, Math.min(1, 0.3 + connectivity), attrs.clusterIndex))
  })
  renderer.refresh()
})

const graphData = computed(() => buildSemanticViewModel({
  graph: selectSemanticGraphSource({
    inspectionGraph: searchStore.indexInspection?.graph
  }),
  savedPositions: positions.value,
  width: 1800,
  height: 1200
}))

const positionedEdges = computed(() => {
  const byId = new Map(positionedNodes.value.map((node) => [node.id, node]))
  return graphData.value.edges
    .map((edge) => {
      const source = byId.get(edge.source)
      const target = byId.get(edge.target)
      if (!source || !target) return null
      return {
        id: `${edge.source}->${edge.target}`,
        x1: source.x + 88,
        y1: source.y + 40,
        x2: target.x + 88,
        y2: target.y + 40,
        type: edge.type || 'semantic'
      }
    })
    .filter(Boolean)
})

const graphPanel = computed(() =>
  buildChatContextPanel({ graph: searchStore.indexInspection?.graph })
)

const graphSummary = computed(() => {
  const summary = graphPanel.value.summary
  if (!summary) return ''
  const parts = []
  if (summary.nodes) parts.push(`${summary.nodes} nodes`)
  if (summary.semanticEdges) parts.push(`${summary.semanticEdges} semantic links`)
  return parts.join(' \u00b7 ')
})

const chatModeLabel = computed(() => {
  const mode = store.chatMode
  if (mode === 'simple') return 'Simple'
  if (mode === 'graph') return 'Graph-aware'
  return 'Advanced'
})

const query = computed({
  get: () => store.query,
  set: (value) => store.setQuery(value)
})

watch(
  () => store.query,
  (value, oldValue) => {
    if (value === oldValue) return
    if (!store.isOpen) return
    selectedIndex.value = 0
    debouncedSearch()
  }
)

watch(
  () => store.mode,
  (value, oldValue) => {
    if (value !== oldValue && store.isOpen) {
      selectedIndex.value = 0
      store.search()
    }
  }
)

watch(
  () => store.isOpen,
  async (value) => {
    if (value) {
      selectedIndex.value = 0
      await focusInput()
      store.refreshStatus()
      clearInterval(pollTimer)
      pollTimer = setInterval(() => {
        store.refreshStatus()
      }, 1500)
    } else {
      clearInterval(pollTimer)
      pollTimer = null
    }
  }
)

const matchLabel = computed(() => {
  const matchType = String(props.result?.matchType || '').trim()
  if (matchType === 'hybrid') return 'Semantic + keyword'
  if (matchType === 'semantic') return 'Semantic'
  if (matchType === 'keyword') return 'Keyword'
  return 'Local match'
})

const escapedTokens = computed(() => {
  const query = String(props.query || '').trim()
  if (!query) return []
  const tokens = query.split(/\s+/).filter(Boolean)
  const seen = new Set()
  const escaped = []
  for (const token of tokens) {
    if (token.length < 2) continue
    if (seen.has(token.toLowerCase())) continue
    seen.add(token.toLowerCase())
    escaped.push(token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
  }
  return escaped
})

const counts = computed(() => {
  const indexed = Number(props.status?.indexedDocuments || 0)
  const total = Number(props.status?.totalDocuments || 0)
  if (!indexed && !total) return ''
  return `${indexed}/${total}`
})

const statusText = computed(() => {
  if (previewStore.status === 'preparing') return 'Preparing website preview...'
  if (previewStore.status === 'building') return 'Building website...'
  if (previewStore.status === 'error') return 'Website preview failed.'
  return 'Website preview'
})
